package net.morben.shenggan;

import com.google.gson.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;
import java.util.zip.*;

/** Native launcher localization workspace. Original instance resources are read only. */
final class NativeLocalization {
    private static final Gson JSON=NativeResourceFiles.JSON;
    private static final Pattern TOKEN=Pattern.compile("%(?:(\\d+)\\$)?[-+#0,(<]*\\d*(?:\\.\\d+)?[tT]?[A-Za-z%]|\\$\\{[^{}]+}|\\$\\([^()]+\\)|\\{[^{}\\r\\n]+}|(?:&|§)(?:#[0-9a-fA-F]{6}|[0-9A-FK-ORZa-fk-orz])");
    private final JsonObject input;private final Path data;
    NativeLocalization(JsonObject input,Path data){this.input=input;this.data=data;}
    private String text(String key,String fallback){return NativeResourceFiles.text(input,key,fallback);}
    private static String text(JsonObject object,String key,String fallback){return NativeResourceFiles.text(object,key,fallback);}
    private static void write(Path file,Object value)throws IOException{Files.createDirectories(file.getParent());Path stage=Files.createTempFile(file.getParent(),".language-",".json");try{Files.writeString(stage,JSON.toJson(value),StandardCharsets.UTF_8);Files.move(stage,file,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}finally{Files.deleteIfExists(stage);}}
    private Path project()throws IOException{Path path=Path.of(text("project","")).toAbsolutePath().normalize();if(!path.startsWith(data.resolve("localization"))||!Files.isRegularFile(path.resolve("project.json")))throw new IOException("汉化工作区不存在，请重新读取实例资源。");return path;}
    private static String validID(String id)throws IOException{if(!id.matches("[a-f0-9]{40}"))throw new IOException("实例资源编号无效");return id;}
    private static Path entriesFile(Path project,String id)throws IOException{return project.resolve("sources/"+validID(id)+"/entries.json");}
    private static JsonArray entries(Path project,String id)throws IOException{try{return JsonParser.parseString(Files.readString(entriesFile(project,id))).getAsJsonArray();}catch(JsonParseException e){throw new IOException("无法读取汉化条目",e);}}
    private static String locale(String path){String name=path.substring(path.lastIndexOf('/')+1);return name.substring(0,name.lastIndexOf('.')).toLowerCase(Locale.ROOT);}
    private static String namespace(String path){return path.split("/")[1];}
    private static Map<String,String> parse(byte[] bytes,String path)throws IOException{
        String content=new String(bytes,StandardCharsets.UTF_8).replaceFirst("^\\uFEFF","");Map<String,String> values=new LinkedHashMap<>();
        try{if(path.endsWith(".lang")){Properties p=new Properties();p.load(new StringReader(content));for(String key:p.stringPropertyNames())values.put(key,p.getProperty(key));}
            else{JsonObject object=JsonParser.parseString(content).getAsJsonObject();for(var e:object.entrySet())if(e.getValue().isJsonPrimitive()&&e.getValue().getAsJsonPrimitive().isString())values.put(e.getKey(),e.getValue().getAsString());}
        }catch(RuntimeException e){throw new IOException("无法解析语言文件："+path,e);}return values;
    }
    static List<String> tokens(String text){List<String> values=new ArrayList<>();Matcher m=TOKEN.matcher(text);int sequential=0;while(m.find()){String token=m.group();if(token.startsWith("%")&&!token.equals("%%")){String position=m.group(1);String type=token.substring(token.length()-1).toLowerCase(Locale.ROOT);values.add("%"+(position==null?++sequential:Integer.parseInt(position))+":"+type);}else values.add(token);}Collections.sort(values);return values;}
    static boolean compatible(String english,String translated){return tokens(english).equals(tokens(translated));}
    private static Map<String,byte[]> documents(Path source)throws IOException{
        Map<String,byte[]> files=new TreeMap<>();long total=0;
        if(Files.isDirectory(source)){Path assets=source.resolve("assets");if(!Files.isDirectory(assets))return files;try(var paths=Files.walk(assets,8)){for(Path path:paths.filter(p->Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)).sorted().toList()){String name=source.relativize(path).toString();if(!NativeResourceFiles.language(name)||!NativeResourceFiles.safe(name))continue;try(InputStream in=Files.newInputStream(path)){byte[] b=NativeResourceFiles.bounded(in,4_000_000);total+=b.length;if(total>128_000_000)throw new IOException("单个实例资源的语言文件过大");files.put(name,b);}}}}
        else try(ZipFile zip=new ZipFile(source.toFile())){for(ZipEntry entry:Collections.list(zip.entries())){if(entry.isDirectory()||!NativeResourceFiles.language(entry.getName())||!NativeResourceFiles.safe(entry.getName()))continue;if(files.size()>20_000)throw new IOException("实例资源语言文件数量过多");try(InputStream in=zip.getInputStream(entry)){byte[] b=NativeResourceFiles.bounded(in,4_000_000);total+=b.length;if(total>128_000_000)throw new IOException("单个实例资源的语言文件过大");files.put(entry.getName(),b);}}}
        return files;
    }
    static double formatFromJar(Path jar){try(ZipFile zip=new ZipFile(jar.toFile())){ZipEntry file=zip.getEntry("version.json");if(file==null)return 0;JsonObject root;try(InputStream in=zip.getInputStream(file)){root=JsonParser.parseString(new String(NativeResourceFiles.bounded(in,200_000),StandardCharsets.UTF_8)).getAsJsonObject();}JsonObject pack=root.getAsJsonObject("pack_version");if(pack==null)return 0;if(pack.has("resource_major")){return pack.get("resource_major").getAsInt()+pack.get("resource_minor").getAsDouble()/1000;}return pack.get("resource").getAsDouble();}catch(Exception e){return 0;}}
    static double fallbackFormat(String version){Map<String,Integer> formats=Map.ofEntries(Map.entry("1.16.5",6),Map.entry("1.17",7),Map.entry("1.17.1",7),Map.entry("1.18",8),Map.entry("1.18.1",8),Map.entry("1.18.2",8),Map.entry("1.19",9),Map.entry("1.19.1",9),Map.entry("1.19.2",9),Map.entry("1.19.3",12),Map.entry("1.19.4",13),Map.entry("1.20",15),Map.entry("1.20.1",15),Map.entry("1.20.2",18),Map.entry("1.20.3",22),Map.entry("1.20.4",22),Map.entry("1.20.5",32),Map.entry("1.20.6",32),Map.entry("1.21",34),Map.entry("1.21.1",34),Map.entry("1.21.2",42),Map.entry("1.21.3",42),Map.entry("1.21.4",46),Map.entry("1.21.5",55),Map.entry("1.21.6",63),Map.entry("1.21.7",64),Map.entry("1.21.8",64));if(formats.containsKey(version))return formats.get(version);if(version.matches("1\\.(6|7|8)(\\..*)?"))return 1;if(version.matches("1\\.(9|10)(\\..*)?"))return 2;if(version.matches("1\\.(11|12)(\\..*)?"))return 3;if(version.matches("1\\.(13|14)(\\..*)?"))return 4;if(version.matches("1\\.15(\\..*)?"))return 5;return 0;}
    Map<String,Object> scan(List<Map<String,Object>> resources)throws Exception{
        Path run=Path.of(text("runDirectory",""));Path project=data.resolve("localization/"+NativeResourceFiles.digest((run+":"+text("id","")).getBytes(StandardCharsets.UTF_8)));Files.createDirectories(project);
        List<Map<String,Object>> all=new ArrayList<>(resources);for(String name:List.of("kubejs","resources")){Path folder=run.resolve(name);if(Files.isDirectory(folder.resolve("assets")))all.add(NativeResourceFiles.item(folder,"loose",name,null,null,data));}
        all.addAll(NativeTextAssets.discover(run,data));
        String jar=text("clientJar","");if(!jar.isBlank()&&Files.isRegularFile(Path.of(jar))){var base=NativeResourceFiles.item(Path.of(jar),"minecraft","Minecraft",null,null,data);all.add(0,base);}
        List<Map<String,Object>> sources=new ArrayList<>();List<String> warnings=new ArrayList<>();long extracted=0;
        for(var resource:all){Path file=Path.of((String)resource.get("path"));String id=NativeResourceFiles.digest(file.toString().getBytes(StandardCharsets.UTF_8));Path folder=project.resolve("sources/"+id);Map<String,byte[]> documents;
            try{documents=NativeTextAssets.mode((String)resource.get("kind"))?NativeTextAssets.extract(file,(String)resource.get("kind"),folder,run,warnings):documents(file);if("minecraft".equals(resource.get("kind"))&&input.has("minecraftLanguages"))for(var language:input.getAsJsonObject("minecraftLanguages").entrySet()){
                if(!NativeResourceFiles.language(language.getKey())||!NativeResourceFiles.safe(language.getKey()))continue;
                try(InputStream in=Files.newInputStream(Path.of(language.getValue().getAsString()))){documents.put(language.getKey(),NativeResourceFiles.bounded(in,4_000_000));}catch(IOException e){warnings.add("Minecraft："+language.getKey()+" 读取失败");}
            }}catch(Exception e){warnings.add(file.getFileName()+"："+e.getMessage());continue;}if(documents.isEmpty())continue;
            Map<String,Map<String,String>> english=new TreeMap<>(),target=new TreeMap<>();List<String> files=new ArrayList<>();Set<String> languages=new TreeSet<>();
            for(var doc:documents.entrySet()){extracted+=doc.getValue().length;if(extracted>256_000_000L)throw new IOException("语言文件总量超过当前读取上限，请分批选择实例资源。");String path=doc.getKey();Path destination=folder.resolve("original/"+path);Files.createDirectories(destination.getParent());Files.write(destination,doc.getValue());files.add(path);String locale=locale(path);languages.add(locale);
                if(locale.equals("en_us")||locale.equals("en_gb")||locale.equals("zh_cn"))try{Map<String,String> values=parse(doc.getValue(),path);String ns=namespace(path);if(locale.equals("zh_cn"))target.computeIfAbsent(ns,k->new LinkedHashMap<>()).putAll(values);else if(locale.equals("en_us")||!english.containsKey(ns))english.computeIfAbsent(ns,k->new LinkedHashMap<>()).putAll(values);}catch(IOException e){warnings.add(e.getMessage());}
            }
            for(var ns:target.entrySet())english.computeIfAbsent(ns.getKey(),key->new LinkedHashMap<>()).putAll(ns.getValue().entrySet().stream().filter(e->!english.getOrDefault(ns.getKey(),Map.of()).containsKey(e.getKey())).collect(java.util.stream.Collectors.toMap(Map.Entry::getKey,Map.Entry::getValue)));
            Map<String,JsonObject> old=new HashMap<>();if(Files.isRegularFile(folder.resolve("entries.json")))for(JsonElement e:entries(project,id)){JsonObject o=e.getAsJsonObject();old.put(text(o,"id",""),o);}
            List<Map<String,Object>> rows=new ArrayList<>();int translated=0;
            for(var ns:english.entrySet())for(var entry:new TreeMap<>(ns.getValue()).entrySet()){String key=ns.getKey()+"::"+entry.getKey();String value=target.getOrDefault(ns.getKey(),Map.of()).getOrDefault(entry.getKey(),"");String origin=value.isEmpty()?"pending":"embedded";JsonObject previous=old.get(key);if(previous!=null&&text(previous,"source","").equals(entry.getValue())&&!text(previous,"translation","").isEmpty()&&!text(previous,"origin","").equals("embedded")){value=text(previous,"translation","");origin=text(previous,"origin","manual");}String issue=!value.isEmpty()&&!compatible(entry.getValue(),value)?"格式占位符不一致":"";if(!value.isEmpty()&&issue.isEmpty())translated++;
                rows.add(new LinkedHashMap<>(Map.of("id",key,"namespace",ns.getKey(),"key",entry.getKey(),"source",entry.getValue(),"translation",value,"origin",origin,"issue",issue)));}
            write(folder.resolve("entries.json"),rows);Map<String,Object> source=new LinkedHashMap<>(resource);source.put("id",id);source.put("languageFiles",files.size()+(NativeResourceFiles.object(folder.resolve(NativeTextAssets.INDEX)).has("documents")?NativeResourceFiles.object(folder.resolve(NativeTextAssets.INDEX)).getAsJsonArray("documents").size()-2:0));source.put("languages",languages);source.put("entries",rows.size());source.put("translated",translated);source.put("files",files);sources.add(source);
        }
        double format=jar.isBlank()?0:formatFromJar(Path.of(jar));if(format==0)format=fallbackFormat(text("version",""));Map<String,Object> result=new LinkedHashMap<>();result.put("project",project.toString());result.put("name",text("name",text("id","Minecraft")));result.put("version",text("version",""));result.put("loader",text("loader",""));result.put("packFormat",format);result.put("sources",sources);result.put("warnings",warnings.stream().limit(60).toList());write(project.resolve("project.json"),result);return result;
    }
    Map<String,Object> read()throws Exception{return Map.of("entries",entries(project(),text("resource","")));}
    Map<String,Object> save()throws Exception {
        Path project=project();JsonArray changes=input.has("changes")?input.getAsJsonArray("changes"):new JsonArray();
        if(!input.has("changes")){JsonObject change=new JsonObject();change.addProperty("resource",text("resource",""));change.addProperty("entry",text("entry",""));change.addProperty("translation",text("translation",""));changes.add(change);}
        boolean automatic=input.has("onlyMissing")&&input.get("onlyMissing").getAsBoolean();
        String origin=text("origin","manual").equals("machine")?"machine":"manual";
        Map<String,JsonArray> changed=new LinkedHashMap<>();int saved=0,skipped=0;
        for(JsonElement value:changes){JsonObject change=value.getAsJsonObject();String resource=validID(text(change,"resource",""));JsonArray rows=changed.get(resource);if(rows==null){rows=entries(project,resource);changed.put(resource,rows);}boolean found=false;
            for(JsonElement e:rows){JsonObject row=e.getAsJsonObject();if(!text(row,"id","").equals(text(change,"entry","")))continue;found=true;
                if(automatic&&((!text(row,"translation","").isEmpty()&&text(row,"issue","").isEmpty())||!text(row,"source","").equals(text(change,"source","")))){skipped++;break;}
                String translated=text(change,"translation","");if(translated.length()>100_000)throw new IOException("条目过长");
                if(automatic&&(translated.isEmpty()||!compatible(text(row,"source",""),translated))){skipped++;break;}
                if(!translated.isEmpty()&&!compatible(text(row,"source",""),translated))throw new IOException("译文的格式占位符与原文不一致："+text(row,"key","")+"，请保留 %s、%1$s、{0} 等标记。");
                row.addProperty("translation",translated);row.addProperty("origin",translated.isEmpty()?"pending":origin);row.addProperty("issue","");saved++;break;
            }
            if(!found)throw new IOException("未找到这个语言条目");
        }
        for(var e:changed.entrySet())write(entriesFile(project,e.getKey()),e.getValue());updateCounts(project);
        return Map.of("saved",saved,"skipped",skipped,"project",NativeResourceFiles.object(project.resolve("project.json")));
    }
    Map<String,Object> pending()throws Exception {
        Path project=project();int limit=Math.max(1,Math.min(512,input.has("limit")?input.get("limit").getAsInt():128));
        Set<String> skip=new HashSet<>();if(input.has("skip"))for(JsonElement e:input.getAsJsonArray("skip"))skip.add(e.getAsString());
        List<Map<String,String>> result=new ArrayList<>();int pending=0;
        for(JsonObject source:selected(project)){String resource=text(source,"id","");for(JsonElement e:entries(project,resource)){JsonObject row=e.getAsJsonObject();if(!text(row,"translation","").isEmpty()&&text(row,"issue","").isEmpty())continue;pending++;String id=text(row,"id","");if(result.size()<limit&&!skip.contains(resource+"/"+id))result.add(Map.of("resource",resource,"id",id,"source",text(row,"source","")));}}
        return Map.of("entries",result,"pending",pending);
    }
    private List<JsonObject> selected(Path project)throws IOException{JsonObject metadata=NativeResourceFiles.object(project.resolve("project.json"));Set<String> ids=new HashSet<>();if(input.has("selected"))for(JsonElement e:input.getAsJsonArray("selected"))ids.add(validID(e.getAsString()));if(input.has("selected")&&ids.isEmpty())throw new IOException("请选择至少一个实例资源");List<JsonObject> selected=new ArrayList<>();for(JsonElement e:metadata.getAsJsonArray("sources")){JsonObject source=e.getAsJsonObject();if(ids.isEmpty()||ids.contains(text(source,"id","")))selected.add(source);}if(selected.isEmpty())throw new IOException("请选择至少一个实例资源");return selected;}
    private void updateCounts(Path project)throws IOException{JsonObject metadata=NativeResourceFiles.object(project.resolve("project.json"));for(JsonElement e:metadata.getAsJsonArray("sources")){JsonObject source=e.getAsJsonObject();int count=0;for(JsonElement row:entries(project,text(source,"id",""))){JsonObject entry=row.getAsJsonObject();if(!text(entry,"translation","").isEmpty()&&text(entry,"issue","").isEmpty())count++;}source.addProperty("translated",count);}write(project.resolve("project.json"),metadata);}
    Map<String,Object> translate()throws Exception{Path project=project();JsonObject metadata=NativeResourceFiles.object(project.resolve("project.json"));Path community=NativeCommunityLanguages.download(text(metadata,"version",""),text(metadata,"loader",""),data);int filled=0,skipped=0;List<String> warnings=new ArrayList<>();
        try(ZipFile zip=community==null?null:new ZipFile(community.toFile())){if(zip==null)warnings.add("社区译库当前不可用，已保留资源内中文与待翻译条目。");Map<String,Map<String,String>> dictionaries=new HashMap<>();
            for(JsonObject source:selected(project)){String id=text(source,"id","");JsonArray rows=entries(project,id);for(JsonElement value:rows){JsonObject row=value.getAsJsonObject();if(!text(row,"translation","").isEmpty()&&text(row,"issue","").isEmpty())continue;String ns=text(row,"namespace","");if(!dictionaries.containsKey(ns)){Map<String,String> dict=new HashMap<>();if(zip!=null)for(String extension:List.of("json","lang")){ZipEntry entry=zip.getEntry("assets/"+ns+"/lang/zh_cn."+extension);if(entry==null)entry=zip.getEntry("assets/"+ns+"/lang/zh_CN."+extension);if(entry!=null)try(InputStream in=zip.getInputStream(entry)){dict.putAll(parse(NativeResourceFiles.bounded(in,4_000_000),entry.getName()));}}dictionaries.put(ns,dict);}String translated=dictionaries.get(ns).get(text(row,"key",""));if(translated!=null&&compatible(text(row,"source",""),translated)){row.addProperty("translation",translated);row.addProperty("origin","community");row.addProperty("issue","");filled++;}else skipped++;}write(entriesFile(project,id),rows);}}
        updateCounts(project);return Map.of("project",NativeResourceFiles.object(project.resolve("project.json")),"filled",filled,"pending",skipped,"warnings",warnings);
    }
    Map<String,Object> importTranslations()throws Exception{Path project=project(),file=Path.of(text("file",""));Map<String,Map<String,String>> translated=new HashMap<>();
        if(file.getFileName().toString().toLowerCase(Locale.ROOT).endsWith(".zip")){for(var doc:documents(file).entrySet())if(locale(doc.getKey()).equals("zh_cn"))translated.computeIfAbsent(namespace(doc.getKey()),k->new HashMap<>()).putAll(parse(doc.getValue(),doc.getKey()));}
        else{List<JsonObject> selection=selected(project);Set<String> namespaces=new HashSet<>();for(JsonObject source:selection)for(JsonElement e:entries(project,text(source,"id","")))namespaces.add(text(e.getAsJsonObject(),"namespace",""));if(namespaces.size()!=1)throw new IOException("单个 lang 文件需要只选择一个命名空间，多个命名空间请导入资源包 ZIP。");try(InputStream in=Files.newInputStream(file)){translated.put(namespaces.iterator().next(),parse(NativeResourceFiles.bounded(in,4_000_000),file.getFileName().toString()));}}
        int added=0,rejected=0;for(JsonObject source:selected(project)){String id=text(source,"id","");JsonArray rows=entries(project,id);for(JsonElement e:rows){JsonObject row=e.getAsJsonObject();String value=translated.getOrDefault(text(row,"namespace",""),Map.of()).get(text(row,"key",""));if(value==null)continue;if(!compatible(text(row,"source",""),value)){rejected++;continue;}row.addProperty("translation",value);row.addProperty("origin","manual");row.addProperty("issue","");added++;}write(entriesFile(project,id),rows);}updateCounts(project);return Map.of("project",NativeResourceFiles.object(project.resolve("project.json")),"imported",added,"rejected",rejected);}
    Map<String,Object> applyTextAssets()throws Exception{Path project=project();List<NativeTextAssets.Patch> patches=new ArrayList<>();for(JsonObject source:selected(project))if(NativeTextAssets.mode(text(source,"kind","")))patches.addAll(NativeTextAssets.patches(project.resolve("sources/"+text(source,"id","")),entries(project,text(source,"id","")),false));return NativeTextAssets.apply(Path.of(text("runDirectory","")),data,patches);}
    private static byte[] languageBytes(Map<String,String> values,boolean legacy){if(!legacy)return JSON.toJson(new TreeMap<>(values)).getBytes(StandardCharsets.UTF_8);StringBuilder text=new StringBuilder();for(var e:new TreeMap<>(values).entrySet())text.append(e.getKey().replace("=","\\=")).append('=').append(e.getValue().replace("\\","\\\\").replace("\n","\\n").replace("\r","\\r")).append('\n');return text.toString().getBytes(StandardCharsets.UTF_8);}
    private static void entry(ZipOutputStream zip,String name,byte[] bytes,Set<String> written)throws IOException{if(!NativeResourceFiles.safe(name)||!written.add(name))throw new IOException("语言包目标路径冲突："+name);zip.putNextEntry(new ZipEntry(name));zip.write(bytes);zip.closeEntry();}
    Map<String,Object> export()throws Exception{Path project=project();JsonObject metadata=NativeResourceFiles.object(project.resolve("project.json"));Path output=Path.of(text("output","")).toAbsolutePath().normalize();if(Files.exists(output))throw new IOException("目标文件已存在，请使用新的文件名。");String name=text("packName","").trim();if(name.isEmpty()||name.length()>150)throw new IOException("请填写不超过 150 字的资源包名称。");double format=input.has("packFormat")?input.get("packFormat").getAsDouble():metadata.get("packFormat").getAsDouble();if(format<=0||format>10000)throw new IOException("未能识别此版本的资源包格式，请填写正确的格式号。");boolean raw=text("mode","translated").equals("source"),legacy=format<4;List<JsonObject> selected=selected(project);Map<String,Map<String,String>> english=new TreeMap<>(),target=new TreeMap<>();List<Map<String,Object>> catalog=new ArrayList<>();List<Map<String,Object>> resources=new ArrayList<>();int pending=0;boolean hasCommunity=false;
        for(JsonObject source:selected){String id=text(source,"id","");resources.add(Map.of("id",id,"name",text(source,"name",""),"kind",text(source,"kind","")));for(JsonElement e:entries(project,id)){JsonObject row=e.getAsJsonObject();String ns=text(row,"namespace",""),key=text(row,"key",""),en=text(row,"source",""),zh=text(row,"translation","");english.computeIfAbsent(ns,k->new TreeMap<>()).put(key,en);boolean valid=!zh.isEmpty()&&compatible(en,zh);if(!valid)pending++;target.computeIfAbsent(ns,k->new TreeMap<>()).put(key,raw||!valid?en:zh);hasCommunity|=!raw&&valid&&text(row,"origin","").equals("community");if(raw)catalog.add(Map.of("resource",text(source,"name",""),"namespace",ns,"key",key,"source",en,"translation","","tokens",tokens(en)));}}
        if(target.isEmpty())throw new IOException("所选实例资源没有可导出的语言条目。");Files.createDirectories(output.getParent());if(Files.getFileStore(output.getParent()).getUsableSpace()<64*1024*1024)throw new IOException("磁盘空间不足，无法打包语言资源。");Path stage=Files.createTempFile(output.getParent(),".harbor-lang-",".zip");Set<String> written=new HashSet<>();
        try{try(ZipOutputStream zip=new ZipOutputStream(Files.newOutputStream(stage),StandardCharsets.UTF_8)){zip.setLevel(6);Map<String,Object> pack=new LinkedHashMap<>();pack.put("description",name);pack.put("pack_format",(int)format);if(format>=65){int major=(int)format,minor=(int)Math.round((format-major)*1000);pack.put("min_format",List.of(major,minor));pack.put("max_format",List.of(major,minor));}entry(zip,"pack.mcmeta",JSON.toJson(Map.of("pack",pack)).getBytes(StandardCharsets.UTF_8),written);String extension=legacy?"lang":"json";
                for(var ns:target.entrySet()){entry(zip,"assets/"+ns.getKey()+"/lang/zh_cn."+extension,languageBytes(ns.getValue(),legacy),written);if(raw)entry(zip,"assets/"+ns.getKey()+"/lang/en_us."+extension,languageBytes(english.get(ns.getKey()),legacy),written);}
                int textFiles=0;for(JsonObject source:selected)textFiles+=NativeTextAssets.export(project.resolve("sources/"+text(source,"id","")),entries(project,text(source,"id","")),zip,raw,written);
                if(raw){for(JsonObject source:selected){String id=text(source,"id","");for(JsonElement e:source.getAsJsonArray("files")){String relative=e.getAsString();Path file=project.resolve("sources/"+id+"/original/"+relative);try(InputStream in=Files.newInputStream(file)){entry(zip,"original-lang/"+id+"/"+relative,NativeResourceFiles.bounded(in,4_000_000),written);}}}entry(zip,"AI-translation.json",JSON.toJson(Map.of("target","zh_cn","resources",resources,"entries",catalog)).getBytes(StandardCharsets.UTF_8),written);}
                String readme=raw?"MC Harbor 未汉化语言资源包\n\nassets 中 zh_cn 的值为英文原文，尚未汉化。original-lang 保留所选实例资源的全部原始 lang 文件，按资源编号区分，避免同名覆盖。AI-translation.json 提供来源、命名空间、键、英文与必须保留的占位符。\n\n请让 AI 只翻译 assets/<namespace>/lang/zh_cn 文件的值，保留键、%s / %1$s / {0} 等占位符以及 JSON / LANG 语法。返回同结构 ZIP 后可用 MC Harbor“导入译文”导入。pack.mcmeta 描述为资源包名称。无需修改原 JAR。original-text 中另存 FTB 任务 / 数据包的原文，映射键同样在 assets 中，翻译后先导回工作区，再应用任务 / 数据包；不要让 AI 修改任务 ID、指令或奖励条件。\n":"MC Harbor 实例资源汉化包\n\n未覆盖条目保留英文，不冒充已完成。原实例资源未改写。请在游戏中启用本资源包并置于需要覆盖的资源包上方。FTB 任务 / 数据包的可用译文另置于 overrides，需使用启动器“应用任务 / 数据包”或按实例根目录合并，资源包本身不能代替任务配置。\n";
                if(hasCommunity)readme+="\n包含 CFPAOrg Minecraft Mod Language Package 社区译文；原项目与贡献者：https://github.com/CFPAOrg/Minecraft-Mod-Language-Package\n社区译文许可：CC BY-NC-SA 4.0 https://creativecommons.org/licenses/by-nc-sa/4.0/\n已按所选实例资源进行筛选与合并；手动改动另由用户负责。\n";entry(zip,raw?"AI-README.txt":"README.txt",readme.getBytes(StandardCharsets.UTF_8),written);entry(zip,"MC-harbor-manifest.json",JSON.toJson(Map.of("name",name,"version",text(metadata,"version",""),"mode",raw?"source":"translated","resources",resources,"pending",pending,"communityTranslations",hasCommunity)).getBytes(StandardCharsets.UTF_8),written);
            }try(ZipFile zip=new ZipFile(stage.toFile())){byte[] b=new byte[65536];for(ZipEntry e:Collections.list(zip.entries())){CRC32 crc=new CRC32();try(InputStream in=zip.getInputStream(e)){for(int n;(n=in.read(b))>0;)crc.update(b,0,n);}if(crc.getValue()!=e.getCrc())throw new IOException("语言资源包校验失败");}}Files.move(stage,output);return Map.of("path",output.toString(),"entries",target.values().stream().mapToInt(Map::size).sum(),"pending",pending,"sources",selected.size(),"mode",raw?"source":"translated");
        }finally{Files.deleteIfExists(stage);}
    }
}
